class EmergencyCardPage extends StatefulWidget{const EmergencyCardPage({super.key});@override State<EmergencyCardPage> createState()=>_EmergencyCardPageState();}
class _EmergencyCardPageState extends State<EmergencyCardPage>{final allergies=TextEditingController(),contact=TextEditingController(),notes=TextEditingController();@override void initState(){super.initState();_load();}Future<void>_load()async{final p=await SharedPreferences.getInstance();allergies.text=p.getString('emergency_allergies')??'';contact.text=p.getString('emergency_contact')??'';notes.text=p.getString('emergency_notes')??'';if(mounted)setState((){});}Future<void>_save()async{final p=await SharedPreferences.getInstance();await p.setString('emergency_allergies',allergies.text);await p.setString('emergency_contact',contact.text);await p.setString('emergency_notes',notes.text);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Emergency card saved')));}String _text(){final meds=Hive.box<Medication>('medications').values.where((m)=>!m.isCompleted).map((m)=>'• ${m.name} ${m.dosage} (${m.isAsNeeded?'as needed':m.times.join(', ')})').join('\n');return 'DoseBuddy Emergency Medication Card\n\nCURRENT MEDICATIONS\n${meds.isEmpty?'None listed':meds}\n\nALLERGIES\n${allergies.text.isEmpty?'None listed':allergies.text}\n\nEMERGENCY CONTACT\n${contact.text.isEmpty?'Not listed':contact.text}\n\nNOTES\n${notes.text.isEmpty?'None':notes.text}';}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Emergency Card'),actions:[IconButton(onPressed:()=>Share.share(_text()),icon:const Icon(Icons.ios_share))]),body:ListView(padding:const EdgeInsets.all(20),children:[Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:const Color(0xFF5B67CA),borderRadius:BorderRadius.circular(24)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Emergency Medication Card',style:TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.w900)),const SizedBox(height:12),...Hive.box<Medication>('medications').values.where((m)=>!m.isCompleted).map((m)=>Padding(padding:const EdgeInsets.only(bottom:6),child:Text('${m.name} • ${m.dosage}',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w700))))])),const SizedBox(height:20),TextField(controller:allergies,maxLines:2,decoration:const InputDecoration(labelText:'Known allergies',border:OutlineInputBorder())),const SizedBox(height:14),TextField(controller:contact,decoration:const InputDecoration(labelText:'Emergency contact',border:OutlineInputBorder())),const SizedBox(height:14),TextField(controller:notes,maxLines:3,decoration:const InputDecoration(labelText:'Important notes',border:OutlineInputBorder())),const SizedBox(height:18),FilledButton.icon(onPressed:_save,icon:const Icon(Icons.save_outlined),label:const Text('Save emergency card')),const SizedBox(height:8),const Text('Only information you enter here is included when you share this card.',textAlign:TextAlign.center,style:TextStyle(color:Colors.grey,fontSize:12))]));}
